// components/ReviewCard.jsx

import React from 'react';
import { Link } from 'react-router-dom';

function ReviewCard({ id, username, title, text, images = [], createdAt, likes = 0 }) {
  return (
    <article className="card fade-in" style={{ marginBottom: 16 }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div>
          <div style={{ fontSize: 13, color: '#666' }}>{username}</div>
          {title && <h3 style={{ margin: '6px 0' }}>{title}</h3>}
        </div>
        <div style={{ fontSize: 12, color: '#999' }}>{createdAt ? new Date(createdAt).toLocaleDateString() : ''}</div>
      </div>

      <p style={{ color: '#333', lineHeight: 1.6, marginTop: 8 }}>{text}</p>

      {images && images.length > 0 && (
        <div style={{ display: 'flex', gap: 8, marginTop: 10 }}>
          {images.slice(0,3).map((src, i) => (
            <img key={i} src={src} alt={`img-${i}`} style={{ width: 96, height: 96, objectFit: 'cover', borderRadius: 8 }} />
          ))}
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginTop: 12 }}>
        <div style={{ color: '#777', fontSize: 13 }}>좋아요 {likes}</div>
        <Link to={`/review/${id}`} style={{ textDecoration: 'none' }}>
          <button className="btn" style={{ padding: '8px 12px', borderRadius: 8, border: '1px solid #eee', background: '#fafafa' }}>자세히 보기</button>
        </Link>
      </div>
    </article>
  );
}

export default ReviewCard;
